const inputItem = $input.first()?.json || {};
const headers = inputItem.headers || {};
const signatureHeader = headers['x-hub-signature-256'] || headers['X-Hub-Signature-256'];
const rawBody = inputItem.body !== undefined ? inputItem.body : inputItem;

let isValid = false;
if (signatureHeader) {
  try {
    const cryptoLib = (function() {
      try {
        const r = (typeof require !== 'undefined' ? require : (globalThis['req' + 'uire'] || null));
        return r ? r('crypto') : null;
      } catch (_) {
        return null;
      }
    })();

    if (cryptoLib) {
      const secret = 'resume001122--';
      const payloadString = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);
      const expectedSignature = 'sha256=' + cryptoLib
        .createHmac('sha256', secret)
        .update(payloadString)
        .digest('hex');

      const receivedBuffer = Buffer.from(signatureHeader);
      const expectedBuffer = Buffer.from(expectedSignature);

      if (receivedBuffer.length === expectedBuffer.length) {
        isValid = cryptoLib.timingSafeEqual(receivedBuffer, expectedBuffer);
      } else {
        isValid = false;
      }
    }
  } catch (err) {
    isValid = false;
  }
}

if (!isValid) {
  return [];
}

return [{
  json: {
    isValid,
    ...(typeof rawBody === 'object' ? rawBody : { body: rawBody })
  }
}];

const body = $json.body || $json;
const headCommit = body.head_commit || (body.commits && body.commits[0]) || {};

const repo_name = body.repository?.name || 'resume-auto-updater';
const repo_owner = body.repository?.owner?.login || body.repository?.owner?.name || 'SyncBuilds';
const branch_ref = body.ref ? body.ref.replace('refs/heads/', '') : 'main';
const commit_message = headCommit.message || 'Auto-update codebase';
const commit_author = headCommit.author?.username || headCommit.author?.name || 'unknown-author';
const commit_timestamp = headCommit.timestamp || new Date().toISOString();

const added = headCommit.added || [];
const modified = headCommit.modified || [];
const removed = headCommit.removed || [];
const modified_files = [...new Set([...added, ...modified, ...removed])];

// Map user_id for Day 6 live backend integration
const user_id = body.user_id || $env.DEFAULT_USER_ID || 'fa9690b9-58e0-49a8-8593-8973c72be3b4';

return {
  user_id,
  repo_name,
  repo_owner,
  branch_ref,
  commit_message,
  commit_author,
  commit_timestamp,
  modified_files,
  trigger_source: 'github_webhook'
};

const input = $input.first()?.json || {};
const commitData = $('Code in JavaScript')?.first()?.json || {};

const repo_name = input.repo_name || commitData.repo_name || 'resume-auto-updater';
const user_id = input.user_id || commitData.user_id || 'fa9690b9-58e0-49a8-8593-8973c72be3b4';
const statusCode = input.statusCode || input.error?.statusCode || 500;
const errorDetail = input.error?.message || input.message || input.detail || 'Pipeline execution failed';
const timestamp = new Date().toISOString();

// Red color (#E02424 -> 14689316 decimal) for Discord rich embed
const embedColor = 14689316;

const payload = {
  content: '🚨 **Resume Auto-Updater Pipeline Error**',
  embeds: [
    {
      title: '■ Resume Auto-Updater Pipeline Error',
      color: embedColor,
      timestamp: timestamp,
      fields: [
        {
          name: 'Repository',
          value: String(repo_name),
          inline: true
        },
        {
          name: 'User ID',
          value: String(user_id),
          inline: true
        },
        {
          name: 'HTTP Status',
          value: String(statusCode),
          inline: true
        },
        {
          name: 'Error Detail',
          value: String(errorDetail),
          inline: false
        }
      ],
      footer: {
        text: 'Resume Auto-Updater • Day 6 Automation Pipeline'
      }
    }
  ],
  text: `■ Resume Auto-Updater Pipeline Error in ${repo_name}: ${errorDetail}`,
  attachments: [
    {
      color: '#E02424',
      title: '■ Resume Auto-Updater Pipeline Error',
      fields: [
        { title: 'Repository', value: String(repo_name), short: true },
        { title: 'User ID', value: String(user_id), short: true },
        { title: 'HTTP Status', value: String(statusCode), short: true },
        { title: 'Error Detail', value: String(errorDetail), short: false }
      ],
      ts: Math.floor(Date.now() / 1000)
    }
  ]
};

return [{ json: payload }];
